import { join } from "../../../src/platform/compat/path/index.js";
import { getConfig } from "../../../src/config/index.js";
import { runtime } from "../../../src/platform/adapters/registry.js";
import { getEnv } from "../../../src/platform/index.js";
import { cliLogger } from "../../utils/index.js";
import { DEFAULT_CACHE_DIR } from "../../../src/utils/constants/server.js";
import { getProjectCacheDir } from "../../../src/utils/cache-dir.js";
import { CacheCoordinator } from "../../../src/rendering/index.js";
import { FilesystemCacheStore, KVCacheStore, MemoryCacheStore, RedisCacheStore, } from "../../../src/rendering/index.js";
import { createFileSystem } from "../../../src/platform/index.js";
import { confirmPrompt, logSuccess, logWarning } from "../../utils/index.js";
import { createSpinner } from "../../ui/index.js";
export async function cleanCommand(options) {
    const { projectDir, cache = false, build = false, all = false, force = false } = options;
    if (all && !force) {
        logWarning("This will remove node_modules, .deno, and .veryfront directories.");
        const confirmed = await confirmPrompt("Are you sure you want to clean all project artifacts?", false);
        if (!confirmed) {
            cliLogger.info("Clean operation cancelled.");
            return;
        }
    }
    const spinner = createSpinner("Cleaning project...");
    try {
        if (build || all) {
            spinner.update("Cleaning dist directory...");
            await cleanDirectory(join(projectDir, "dist"));
        }
        if (cache || all) {
            spinner.update("Cleaning cache...");
            await cleanCacheStore(projectDir);
        }
        if (all) {
            spinner.update("Cleaning node_modules and temp directories...");
            const tempDirs = [".veryfront", "node_modules", ".deno"].map((dir) => join(projectDir, dir));
            await Promise.all(tempDirs.map(cleanDirectory));
        }
        spinner.stop();
        logSuccess("Project cleaned successfully.");
    }
    catch (error) {
        spinner.stop();
        throw error;
    }
}
async function cleanDirectory(path) {
    const fs = createFileSystem();
    if (!(await fs.exists(path)))
        return;
    try {
        await fs.remove(path, { recursive: true });
    }
    catch (error) {
        cliLogger.error(`Failed to clean directory ${path}:`, error);
    }
}
function getFrameworkCacheDirectories(projectDir) {
    const frameworkRoots = new Set([
        getProjectCacheDir(projectDir),
        getEnv("VERYFRONT_CACHE_DIR"),
        getEnv("VF_CACHE_DIR"),
    ].filter((root) => !!root));
    const directories = new Set();
    for (const root of frameworkRoots) {
        for (const namespace of [
            "veryfront-mdx-esm",
            "veryfront-http-bundle",
            "veryfront-files",
            "veryfront-modules",
            "veryfront-cycle-manifests",
        ]) {
            directories.add(join(root, namespace));
        }
    }
    const diskRoot = getEnv("VF_DISK_CACHE_DIR");
    if (diskRoot)
        directories.add(join(diskRoot, "veryfront-files"));
    return [...directories];
}
async function cleanCacheStore(projectDir) {
    try {
        const adapter = await runtime.get();
        const config = await getConfig(projectDir, adapter);
        const cacheDir = config.cache?.dir ?? DEFAULT_CACHE_DIR;
        const renderConfig = (config.cache?.render ?? {});
        const store = createRenderCacheStore(renderConfig.type, {
            projectDir,
            cacheDir,
            adapter,
            renderConfig,
        });
        if (store) {
            const coordinator = new CacheCoordinator({ store, ttlMs: renderConfig.ttl });
            await coordinator.clearAll();
            await coordinator.destroy();
        }
        await cleanDirectory(join(projectDir, cacheDir));
        // The framework cache root is separate from the render cache store and
        // holds the compiled modules a dev server keeps across restarts, so a
        // cache clean that leaves them in place is not a clean. Remove only
        // Veryfront-owned directories because other tools can share `.cache`.
        await Promise.all(getFrameworkCacheDirectories(projectDir).map(cleanDirectory));
    }
    catch (error) {
        cliLogger.error("Failed to clean cache store:", error);
        throw error;
    }
}
function createRenderCacheStore(type, context) {
    const { projectDir, cacheDir, renderConfig } = context;
    if (type === "filesystem") {
        return new FilesystemCacheStore({
            baseDir: join(projectDir, cacheDir, "render"),
        });
    }
    if (type === "kv") {
        return new KVCacheStore({
            path: renderConfig.kvPath,
        });
    }
    if (type === "redis") {
        if (!renderConfig.redisUrl)
            return null;
        return new RedisCacheStore({
            url: renderConfig.redisUrl,
            keyPrefix: renderConfig.redisKeyPrefix ?? "veryfront:render:",
            enableFallback: false,
        });
    }
    return new MemoryCacheStore({
        maxEntries: renderConfig.maxEntries,
        ttlMs: renderConfig.ttl,
    });
}
